using System.Collections.Immutable;
using Mist.Application.Contracts;
using Mist.Application.OptionalLocalWorks;
using Mist.Application.Storage;
using Mist.Core.Contracts;
using Mist.Core.OptionalLocalWorks;
using Mist.Infrastructure.Storage;
using Mist.Tests.ChapterFive;
using static Mist.Tests.Storage.StorageCases;
using static Mist.Tests.TestRegistry;
namespace Mist.Tests.OptionalLocalWorks;
public static class OldCityLocalLifeCases
{
    private static readonly Mist.Core.Content.RuntimeCatalog Catalog=Q102.Q102Cases.Catalog();
    public static OldCityLifeContract Contract()=>OldCityLifeContract.ParseJson(File.ReadAllText(Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,"../../../../..","content/source/optional_local_works/old_city_life_contract.json"))));
    private static ProfileStore Store(string name)=>new(Path.Combine(Environment.GetEnvironmentVariable("MISTSEA_TEST_OUTPUT")??Path.GetTempPath(),"old-city-life-normal-"+name+"-"+Guid.NewGuid()),Catalog.ReleaseId);
    private static void Success(CommandResult r)=>Require(r.Status is CommitStatus.Committed or CommitStatus.AlreadyCommitted,StrictJson.Serialize(r));
    public static string MainWorld(BranchSnapshot s)=>StrictJson.Serialize(new{entities=s.Entities.Where(e=>e.Id!="actor"&&!e.Id.StartsWith("R5-O01:",StringComparison.Ordinal)&&!e.Id.StartsWith("R5-O02:",StringComparison.Ordinal)&&!e.Id.StartsWith("material:R5-LOCAL-",StringComparison.Ordinal)).OrderBy(e=>e.Id),items=s.Items.Where(i=>i.Id is not(OldCityLocalLifeService.ReedBoard or OldCityLocalLifeService.LanternBoard or OldCityLocalLifeService.Pot or OldCityLocalLifeService.Sketch)).OrderBy(i=>i.Id),balances=s.Balances.OrderBy(x=>x.Key)});
    public sealed class Run
    {
        public ProfileStore Store {get;}public ChapterFiveCases.Run Chapter {get;}public OldCityLocalLifeService Service {get;}
        public OldCityLifeView View=>Done(Service.ViewAsync());
        public Run(ProfileStore s){Store=s;var p=ChapterFiveCases.ActualArrival(s);Chapter=new(s,p.Service);Service=new(s,p.Service,Contract());Chapter.Material("R5-Q501-R-LANDING");Chapter.Act("register_landing");}
        public void At(string spot)=>Chapter.At(spot);
        public void Discover(string id){Chapter.Material(id=="SC-R5-SIGN"?"R5-O01-R-SIGN":"R5-O02-R-CLAIM");Success(Done(Service.DiscoverAsync(id)));}
        public void Note(string task,params (string Key,string Value)[] fields){At(task==OldCityLocalLifeService.SignTask?"R5-O01.proposal":"R5-O02.claim");var d=Done(Store.GetDraftAsync(task));Done(Service.SaveDraftAsync(task,d?.Revision??0,d?.Id,"The bounded local proposal retains both public memories and the existing maintenance responsibility. Object checks preserve their separate serials, permitted recipients and uncertain claims. No private family content was supplied or read, and the local correction does not change the genuine archive or legal route."));Success(Done(Service.ConfirmMeaningAsync(task,fields.ToImmutableDictionary(x=>x.Key,x=>x.Value),true)));}
        public void SignReady(string main="Reed Lane"){Discover("SC-R5-SIGN");At("R5-O01.keeper");Success(Done(Service.DecideSignAsync("accept")));Success(Done(Service.ConsultResidentsAsync("ROLE-R5-REED-RESIDENT","ROLE-R5-LANTERN-RESIDENT")));At("R5-O01.proposal");string other=main=="Reed Lane"?"Also called Lantern Turn":"Formerly called Reed Lane";Success(Done(Service.ChooseSignAsync(main,other,OldCityLocalLifeService.Crew)));At("R5-O01.sign");Success(Done(Service.InspectSignStockAsync([OldCityLocalLifeService.ReedBoard,OldCityLocalLifeService.LanternBoard])));Success(Done(Service.InstallChosenSignAsync(View.Sign!.Board)));Success(Done(Service.CheckVisibleSignAsync(main,other,View.Sign!.Configuration)));Note(OldCityLocalLifeService.SignTask,("name",main),("other",other),("consultation","both_local_memories"),("maintainer",OldCityLocalLifeService.Crew),("scope","one_marker_no_history_change"));At("R5-O01.keeper");}
        public void PropertyReady(){Discover("SC-R5-LOST");At("R5-O02.keeper");Success(Done(Service.DecidePropertyAsync("accept")));At("R5-O02.object");Success(Done(Service.InspectLocalObjectsAsync([OldCityLocalLifeService.Pot,OldCityLocalLifeService.Sketch])));At("R5-O02.keeper");Success(Done(Service.RequestPropertyScopeAsync(OldCityLocalLifeService.PotClaimant,"object_identity_and_recipient",["object_identity","permitted_recipient"])));Success(Done(Service.DecideWrapperPermissionAsync(OldCityLocalLifeService.SketchOwner,"wrapper_identity_and_title","accept")));At("R5-O02.claim");Success(Done(Service.ComparePotClaimAsync(OldCityLocalLifeService.Pot,"repaired_left_handle","BR-7",OldCityLocalLifeService.PotClaimant)));At("R5-O02.object");Success(Done(Service.CheckMementoTitleAsync(OldCityLocalLifeService.Sketch,"WR-19","WIT-R5-SKETCH-TITLE-01",OldCityLocalLifeService.SketchOwner)));At("R5-O02.keeper");Success(Done(Service.ReturnPotAsync(OldCityLocalLifeService.Pot,OldCityLocalLifeService.PotClaimant)));Success(Done(Service.ReturnSealedMementoAsync(OldCityLocalLifeService.Sketch,OldCityLocalLifeService.SketchOwner)));At("R5-O02.claim");Success(Done(Service.CorrectPrivateAssociationAsync("private_memento_not_case_evidence")));PropertyNote();At("R5-O02.keeper");}
        public void PropertyNote()=>Note(OldCityLocalLifeService.PropertyTask,("pot",OldCityLocalLifeService.Pot),("pot_recipient",OldCityLocalLifeService.PotClaimant),("memento",OldCityLocalLifeService.Sketch),("memento_recipient",OldCityLocalLifeService.SketchOwner),("privacy","contents_not_supplied_or_read"),("correction","private_memento_not_case_evidence"),("unknown_claim","pending_not_accusation"),("scope","local_title_core_evidence_unchanged"));
    }
    public static void Register()
    {
        Add("CP-R5-LIFE-03","Actual zero-XP local consultation permits either remembered name, installs one same inspected board and visible second line, and leaves the unused board and main history exact",()=>
        {foreach(string name in new[]{"Reed Lane","Lantern Turn"}){using var s=Store("sign");var r=new Run(s);r.Discover("SC-R5-SIGN");string main=MainWorld(Done(s.SnapshotAsync()));r.SignReady(name);long seq=s.Session.Sequence;var p=Done(r.Service.PreviewSignHandoverAsync());Require(p.Ready&&s.Session.Sequence==seq);r.Service.ClosePreview(p.Token);Require(Done(r.Service.ConfirmPreviewAsync(p.Token)).Status==CommitStatus.Rejected&&s.Session.Sequence==seq);p=Done(r.Service.PreviewSignHandoverAsync());Success(Done(r.Service.ConfirmPreviewAsync(p.Token)));Success(Done(r.Service.ConfirmPreviewAsync(p.Token)));var snap=Done(s.SnapshotAsync());Require(r.View.Sign!.Completed&&snap.Items.Count(i=>(i.Id is OldCityLocalLifeService.ReedBoard or OldCityLocalLifeService.LanternBoard)&&i.OwnerKind=="installed")==1&&snap.Items.Count(i=>(i.Id is OldCityLocalLifeService.ReedBoard or OldCityLocalLifeService.LanternBoard)&&i.OwnerKind=="warehouse")==1&&snap.Receipts.Count(x=>x.SemanticKey==OldCityLocalLifeService.SignId+":resolution")==1&&Done(r.Service.CurrentStreetSignLabelAsync())!.StartsWith(name,StringComparison.Ordinal)&&MainWorld(snap)==main&&snap.Balances["experience"]==6400&&snap.Receipts.All(x=>!x.SemanticKey.StartsWith("fixture:",StringComparison.Ordinal)));}});
        Add("CP-R5-LIFE-03","Uncertain local pot descriptions stay pending, different serials and family-content access refuse; current wrapper permission supports same object return without touching real evidence",()=>
        {using var s=Store("property");var r=new Run(s);r.Discover("SC-R5-LOST");string main=MainWorld(Done(s.SnapshotAsync()));r.At("R5-O02.keeper");Success(Done(r.Service.DecidePropertyAsync("accept")));r.At("R5-O02.object");Success(Done(r.Service.InspectLocalObjectsAsync([OldCityLocalLifeService.Pot,OldCityLocalLifeService.Sketch])));r.At("R5-O02.keeper");Success(Done(r.Service.RequestPropertyScopeAsync(OldCityLocalLifeService.PotClaimant,"object_identity_and_recipient",["object_identity","permitted_recipient"])));r.At("R5-O02.claim");Success(Done(r.Service.ComparePotClaimAsync(OldCityLocalLifeService.Pot,"intact_right_handle","OTHER",OldCityLocalLifeService.PotClaimant)));Require(!r.View.Property!.PotMatched);Throws<InvalidOperationException>(()=>Done(r.Service.ComparePotClaimAsync("ANOTHER-POT","repaired_left_handle","BR-7",OldCityLocalLifeService.PotClaimant)));Throws<InvalidOperationException>(()=>Done(r.Service.ComparePotClaimAsync(OldCityLocalLifeService.Pot,"repaired_left_handle","BR-7","ANOTHER-CLAIMANT")));r.At("R5-O02.keeper");Throws<InvalidOperationException>(()=>Done(r.Service.ReturnPotAsync(OldCityLocalLifeService.Pot,OldCityLocalLifeService.PotClaimant)));Throws<InvalidOperationException>(()=>Done(r.Service.OpenPrivateFamilyContentAsync()));Throws<InvalidOperationException>(()=>Done(r.Service.DecideWrapperPermissionAsync(OldCityLocalLifeService.SketchOwner,"publish_family_contents","accept")));r.PropertyReady();Throws<InvalidOperationException>(()=>Done(r.Service.ReturnPotAsync(OldCityLocalLifeService.Pot,"ANOTHER-CLAIMANT")));Throws<InvalidOperationException>(()=>Done(r.Service.ReturnSealedMementoAsync("ANOTHER-MEMENTO",OldCityLocalLifeService.SketchOwner)));var p=Done(r.Service.PreviewPropertyHandoverAsync());Success(Done(r.Service.DecideWrapperPermissionAsync(OldCityLocalLifeService.SketchOwner,"wrapper_identity_and_title","withdraw")));Require(Done(r.Service.ConfirmPreviewAsync(p.Token)).Status==CommitStatus.Rejected&&r.View.Property!.SketchReturned);Success(Done(r.Service.DecideWrapperPermissionAsync(OldCityLocalLifeService.SketchOwner,"wrapper_identity_and_title","accept")));r.At("R5-O02.object");Success(Done(r.Service.CheckMementoTitleAsync(OldCityLocalLifeService.Sketch,"WR-19","WIT-R5-SKETCH-TITLE-01",OldCityLocalLifeService.SketchOwner)));r.At("R5-O02.keeper");p=Done(r.Service.PreviewPropertyHandoverAsync());Success(Done(r.Service.ConfirmPreviewAsync(p.Token)));var snap=Done(s.SnapshotAsync());Require(r.View.Property!.Completed&&snap.Items.Single(i=>i.Id==OldCityLocalLifeService.Pot).OwnerId==OldCityLocalLifeService.PotClaimant&&snap.Items.Single(i=>i.Id==OldCityLocalLifeService.Sketch).OwnerId==OldCityLocalLifeService.SketchOwner&&snap.Entities.Any(e=>e.Id==OldCityLocalLifeService.PropertyId+":original-tag")&&MainWorld(snap)==main&&snap.Receipts.Count(x=>x.SemanticKey==OldCityLocalLifeService.PropertyId+":resolution")==1);});
        Add("CP-R5-LIFE-03","Actual saved name proposal has CAS conflict and changed-body or Continue refusal while the physically installed same sign remains current",()=>
        {using var s=Store("cas");var r=new Run(s);r.SignReady();var p=Done(r.Service.PreviewSignHandoverAsync());var d=Done(s.GetDraftAsync(OldCityLocalLifeService.SignTask))!;Done(r.Service.SaveDraftAsync(OldCityLocalLifeService.SignTask,d.Revision,d.Id,d.Body+" Revised."));Throws<StoreConflictException>(()=>Done(r.Service.SaveDraftAsync(OldCityLocalLifeService.SignTask,d.Revision,d.Id,"stale overwrite")));Require(Done(r.Service.ConfirmPreviewAsync(p.Token)).Status==CommitStatus.Rejected&&r.View.Sign!.Installed&&!r.View.Sign.Completed);r.Note(OldCityLocalLifeService.SignTask,("name","Reed Lane"),("other","Also called Lantern Turn"),("consultation","both_local_memories"),("maintainer",OldCityLocalLifeService.Crew),("scope","one_marker_no_history_change"));r.At("R5-O01.keeper");p=Done(r.Service.PreviewSignHandoverAsync());Done(s.ContinueAsync());Require(Done(r.Service.ConfirmPreviewAsync(p.Token)).Status==CommitStatus.Rejected);p=Done(r.Service.PreviewSignHandoverAsync());Success(Done(r.Service.ConfirmPreviewAsync(p.Token)));});
        Add("CP-R5-LIFE-05","Actual normal prior chapters and registered R5 landing export a native local-life entry with no local object, permission or completion seed",()=>
        {using var s=Store("native-entry");var r=new Run(s);r.At("R5-O01.proposal");var snap=Done(s.SnapshotAsync());Require(snap.Balances["experience"]==6400&&r.View.Sign is null&&r.View.Property is null&&!snap.Items.Any(i=>i.Id is OldCityLocalLifeService.ReedBoard or OldCityLocalLifeService.LanternBoard or OldCityLocalLifeService.Pot or OldCityLocalLifeService.Sketch)&&snap.Receipts.All(x=>!x.SemanticKey.StartsWith("fixture:",StringComparison.Ordinal)&&!x.SemanticKey.StartsWith("internal:",StringComparison.Ordinal)));Done(s.CreateCheckpointAsync("manual"));File.WriteAllText(Path.Combine(s.RootPath,"normal-r5-local-life-native-entry.json"),StrictJson.Serialize(new{scope="actual zero-XP preceding four chapters and R4R5 voyage; R5 landing actually registered, both local-life branches unaccepted",profile_root=s.RootPath,experience=6400,actor=r.Chapter.View.Actor,receipts=snap.Receipts,human_native_play="not_run",physical_ime="not_run",language_calibration="human_pending"}));});
    }
}
